WITH unpacked AS (SELECT id, currency, tier_limits, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT id, currency, entry_price, lowest_price, SUM(lowest_price) OVER (PARTITION BY currency) AS currency_sum_lowest_price, AVG(lowest_price) OVER (ORDER BY lowest_price, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS lowest_price_avg_6 FROM unpacked;
